        if m:
            LOG_FILES.append(os.path.join(LOGDIR, fname))

# Parse all log entries: request_id -> list of (timestamp, user, status, latency)
# Actually, we need to keep all attempts per request_id to find the latest
requests = defaultdict(list)

for fpath in LOG_FILES:
    if fpath.endswith('.gz'):
        try:
            with open(fpath, 'rb') as f:
                raw = f.read()
        except:
            continue

        # Use decompressor that tolerates truncated data
        try:
            decompressor = gzip.GzipFile(fileobj=io.BytesIO(raw))
            for line in iter(decompressor.readline, b''):
                decoded = line.decode('utf-8', errors='replace').strip()
                if not decoded:
                    continue
                result = parse_json_line(decoded) or parse_legacy_line(decoded)
                if result:
                    ts, user, request_id, status, latency = result
                    requests[request_id].append(result)
        except:
            # If decompressor fails mid-stream, we already got what we could
            pass
    else:
        with open(fpath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                result = parse_json_line(line) or parse_legacy_line(line)
                if result:
                    ts, user, request_id, status, latency = result
                    requests[request_id].append(result)

# For each request_id, keep only the attempt with the latest timestamp
best_attempts = {}
for req_id, attempts in requests.items():
    best = max(attempts, key=lambda x: x[0])
    best_attempts[req_id] = best

# Find failed requests (status >= 500)
user_failures = defaultdict(list)
for req_id, (ts, user, rid, status, latency) in best_attempts.items():
    if status >= 500:
        user_failures[user].append(latency)

# Compute p95 for each user
results = []
for user, latencies in user_failures.items():
    n = len(latencies)
    if n == 0:
        continue
    latencies_sorted = sorted(latencies)
    rank = math.ceil(0.95 * n)  # 1-based rank
    p95 = latencies_sorted[rank - 1]  # convert to 0-based
    results.append((user, n, p95))

# Sort by failures descending, then user ascending
results.sort(key=lambda x: (-x[1], x[0]))

# Output CSV
print("user,failures,p95_ms")
for user, failures, p95 in results:
    print(f"{user},{failures},{p95}")
